# =============================================================================
# oracle-xe11 (gvenzl/oracle-xe) 전용 변수명 매핑 - 직접 수정 불필요
# -----------------------------------------------------------------------------
# gvenzl 이미지는 Oracle 공식 이미지와 환경변수 이름이 다릅니다.
# compose 에서 default.env → .env → 이 파일 순서로 로딩되며,
# ${...} 는 앞 파일에서 최종 결정된 값으로 치환됩니다.
# (.env 에서 ORACLE_PWD 를 바꾸면 11g 에도 자동 반영)
#
# 값을 바꾸고 싶으면 이 파일이 아니라 default.env / .env 의 ORACLE_PWD 를 수정하세요.
# =============================================================================

# SYS / SYSTEM 비밀번호 (gvenzl: 최초 기동 시 필수)
ORACLE_PASSWORD=${ORACLE_PWD}

# --- gvenzl 전용 옵션 (필요 시 .env 가 아닌 여기서 주석 해제) ---------------
# 최초 기동 시 애플리케이션 사용자 자동 생성 (scripts/xe11/setup 의 SQL 대신 사용 가능)
# APP_USER=app
# APP_USER_PASSWORD=App_Pass_123
#
# 참고: ORACLE_DATABASE(PDB 생성)는 11g 미지원